package counter

// Counter counts occurrences of string keys.
type Counter struct {
	m map[string]int
}

// New returns an empty counter.
func New() *Counter { return &Counter{m: map[string]int{}} }

// Inc adds one to k.
func (c *Counter) Inc(k string) { c.m[k]++ }

// Get returns the count for k.
func (c *Counter) Get(k string) int { return c.m[k] }

// Snapshot returns the current counts.
func (c *Counter) Snapshot() map[string]int { return c.m }

