package counter

import (
	"sync"
	"testing"
)

func TestConcurrentInc(t *testing.T) {
	c := New()
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 100; j++ {
				c.Inc("k")
			}
		}()
	}
	wg.Wait()
	if got := c.Get("k"); got != 5000 {
		t.Fatalf("got %d, want 5000", got)
	}
}

func TestSnapshotIsACopy(t *testing.T) {
	c := New()
	c.Inc("a")
	s := c.Snapshot()
	s["a"] = 99
	s["b"] = 1
	if c.Get("a") != 1 || c.Get("b") != 0 {
		t.Fatal("Snapshot must not share the counter's storage")
	}
	if len(c.Snapshot()) != 1 {
		t.Fatal("snapshot changed the counter")
	}
}

func TestGetMissingIsZero(t *testing.T) {
	if New().Get("nope") != 0 {
		t.Fatal("missing key must read as 0")
	}
}

